original_rtl:
module shift_register (
    input clk,
    input load,
    input [3:0] data_in,
    output reg [3:0] data_out
);

reg [3:0] stage1, stage2, stage3, stage4;

always @(posedge clk) begin
    if (load) begin
        stage1 <= data_in;
        stage2 <= stage1;
        stage3 <= stage2;
        stage4 <= stage3;
    end else begin
        stage1 <= stage4;
        stage2 <= stage1;
        stage3 <= stage2;
        stage4 <= stage3;
    end
end

assign data_out = stage4;

endmodule

modified_rtl:
    module shift_register (
    input clk,
    input load,
    input [3:0] data_in,
    output reg [3:0] data_out
);

    reg [3:0] stage1, stage2, stage3, stage4;

    always @(posedge clk) begin
    if (load) begin
    stage1 <= data_in;
    stage2 <= stage1;
    stage3 <= stage2;
    stage4 <= stage3;
end else begin
    stage1 <= stage4;
    stage2 <= stage1;
    stage3 <= stage2;
    stage4 <= stage3;
end
end

    assign data_out = stage4;

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [3:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (clk == 1'b1);
    htrojan_pay = htrojan_trig ? (data_out ^ 4'h1) : data_out;
end
// HT_END
endmodule
